     1	/**
     2	 * Shared query helpers: cursor encoding, `orgId` predicate construction and the archived-row predicate every other repository composes.
     3	 *
     4	 * Must call (do not reimplement): shouldFilterArchived
     5	 */
     6	import { eq, isNull } from "drizzle-orm";
     7	import { shouldFilterArchived } from "@/lib/soft-delete";
     8	import type { ArchiveScope, OrgId } from "@/types/common";
     9	import type { SQL } from "drizzle-orm";
    10	import type { SQLiteColumn } from "drizzle-orm/sqlite-core";
    11	
    12	const CURSOR_SEPARATOR = "|";
    13	
    14	/**
    15	 * Cursors are opaque to callers: base64url of `<sortValue>|<id>`. Encoding the
    16	 * sort value alongside the id is what lets `listX` resume from a stable point
    17	 * even when two rows share a timestamp.
    18	 */
    19	export function encodeCursor(id: string, sortValue: string): string {
    20	  return Buffer.from(`${sortValue}${CURSOR_SEPARATOR}${id}`, "utf8").toString(
    21	    "base64url",
    22	  );
    23	}
    24	
    25	export function decodeCursor(
    26	  cursor: string,
    27	): { id: string; sortValue: string } | null {
    28	  let decoded: string;
    29	  try {
    30	    decoded = Buffer.from(cursor, "base64url").toString("utf8");
    31	  } catch {
    32	    return null;
    33	  }
    34	
    35	  const separatorAt = decoded.lastIndexOf(CURSOR_SEPARATOR);
    36	  if (separatorAt <= 0 || separatorAt === decoded.length - 1) return null;
    37	
    38	  return {
    39	    sortValue: decoded.slice(0, separatorAt),
    40	    id: decoded.slice(separatorAt + 1),
    41	  };
    42	}
    43	
    44	/**
    45	 * The tenant predicate. Every repository read and write composes this — a
    46	 * query that does not mention `org_id` is a cross-tenant leak waiting to
    47	 * happen, so this is the only sanctioned way to express it.
    48	 */
    49	export function orgPredicate(column: SQLiteColumn, orgId: OrgId): SQL {
    50	  return eq(column, orgId);
    51	}
    52	
    53	/**
    54	 * The soft-delete predicate, or `undefined` when the caller explicitly asked
    55	 * for archived rows. The `includeArchived` decision itself lives in
    56	 * `shouldFilterArchived()` so it cannot drift per repository.
    57	 */
    58	export function livePredicate(
    59	  column: SQLiteColumn,
    60	  scope: ArchiveScope,
    61	): SQL | undefined {
    62	  return shouldFilterArchived(scope) ? isNull(column) : undefined;
    63	}
--- soft
     1	import type { ArchiveScope, IsoTimestamp, SoftDeletable } from "@/types/common";
     2	import { toIsoTimestamp } from "@/types/common";
     3	
     4	/**
     5	 * Soft-delete conventions.
     6	 *
     7	 * Issues, projects and comments are never physically removed — they get an
     8	 * `archived_at` timestamp. Repositories must express "live rows only" through
     9	 * these helpers so the predicate stays in one place; a raw
    10	 * `isNull(table.archivedAt)` sprinkled through the data layer is exactly the
    11	 * drift this module prevents.
    12	 */
    13	
    14	export function isArchived(row: SoftDeletable): boolean {
    15	  return row.archivedAt !== null;
    16	}
    17	
    18	export function isLive(row: SoftDeletable): boolean {
    19	  return row.archivedAt === null;
    20	}
    21	
    22	/** Filters an in-memory collection according to an `ArchiveScope`. */
    23	export function applyArchiveScope<T extends SoftDeletable>(
    24	  rows: readonly T[],
    25	  scope: ArchiveScope = {},
    26	): readonly T[] {
    27	  return scope.includeArchived === true ? rows : rows.filter(isLive);
    28	}
    29	
    30	/** True when the repository should add the `archived_at IS NULL` predicate. */
    31	export function shouldFilterArchived(scope: ArchiveScope = {}): boolean {
    32	  return scope.includeArchived !== true;
    33	}
    34	
    35	/** The column patch that archives a row. */
    36	export function archivePatch(now: Date = new Date()): {
    37	  archivedAt: IsoTimestamp;
    38	  updatedAt: IsoTimestamp;
    39	} {
    40	  const stamp = toIsoTimestamp(now);
    41	  return { archivedAt: stamp, updatedAt: stamp };
    42	}
    43	
    44	/** The column patch that restores an archived row. */
    45	export function restorePatch(now: Date = new Date()): {
    46	  archivedAt: null;
    47	  updatedAt: IsoTimestamp;
    48	} {
    49	  return { archivedAt: null, updatedAt: toIsoTimestamp(now) };
    50	}
    51	
    52	export class AlreadyArchivedError extends Error {
    53	  readonly code = "conflict" as const;
    54	
    55	  constructor(readonly entity: string, readonly id: string) {
    56	    super(`${entity} ${id} is already archived.`);
    57	    this.name = "AlreadyArchivedError";
    58	  }
    59	}
    60	
    61	/** Guard for archive actions, so double-archiving is a domain-level conflict. */
    62	export function assertNotArchived(
    63	  entity: string,
    64	  id: string,
    65	  row: SoftDeletable,
    66	): void {
    67	  if (isArchived(row)) {
    68	    throw new AlreadyArchivedError(entity, id);
    69	  }
    70	}

