     1	/**
     2	 * Scans for issues past `dueAt` and emits `issue.overdue`, which the notification fan-out turns into alerts.
     3	 *
     4	 * Must call (do not reimplement): emit, shouldFilterArchived
     5	 */
     6	import { emit } from "@/lib/event-bus";
     7	import { createLogger } from "@/lib/logger";
     8	import { shouldFilterArchived } from "@/lib/soft-delete";
     9	import * as issueRepo from "@/server/repositories/issue-repository";
    10	import * as usageRepo from "@/server/repositories/usage-repository";
    11	import { toIsoTimestamp } from "@/types/common";
    12	import { runJob } from "./types";
    13	import type { JobResult } from "@/server/jobs/types";
    14	
    15	/** How many organizations one pass sweeps. */
    16	const ORG_BATCH = 50;
    17	
    18	/** Archived issues are never overdue — an archived issue has no due date. */
    19	const LIVE_ONLY = {} as const;
    20	
    21	const logger = createLogger("overdue-issue-job");
    22	
    23	/**
    24	 * Issues already announced this process's lifetime. A later sweep still
    25	 * finds a still-open, still-overdue issue — this is what keeps the job from
    26	 * re-emitting `issue.overdue` for it on every pass.
    27	 */
    28	const reported = new Set<string>();
    29	
    30	/** Test-only: clears the reported set so a fresh scenario starts empty. */
    31	export function resetOverdueTracking(): void {
    32	  reported.clear();
    33	}
    34	
    35	/**
    36	 * Publishes one `issue.overdue` per still-open, past-due issue. The job owns
    37	 * no notification logic: it announces the fact, and whoever cares (in-app
    38	 * alerts, the digest, webhooks) reacts on the bus.
    39	 */
    40	export async function runOverdueIssueJob(now: Date): Promise<JobResult> {
    41	  return runJob("overdue-issues", async (result) => {
    42	    if (!shouldFilterArchived(LIVE_ONLY)) {
    43	      logger.warn("archive scope misconfigured; skipping sweep", {});
    44	      return;
    45	    }
    46	
    47	    const stamp = toIsoTimestamp(now);
    48	    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);
    49	
    50	    for (const orgId of orgIds) {
    51	      const overdue = await issueRepo.listOverdueIssues(orgId, stamp);
    52	
    53	      for (const issue of overdue) {
    54	        if (issue.dueAt === null) continue;
    55	        if (reported.has(issue.id)) continue;
    56	
    57	        try {
    58	          await emit("issue.overdue", {
    59	            orgId,
    60	            actorId: null,
    61	            occurredAt: stamp,
    62	            issueId: issue.id,
    63	            projectId: issue.projectId,
    64	            dueAt: issue.dueAt,
    65	            assigneeId: issue.assigneeId,
    66	          });
    67	          reported.add(issue.id);
    68	          result.processed += 1;
    69	        } catch (error) {
    70	          result.failed += 1;
    71	          logger.error("failed to announce overdue issue", {
    72	            issueId: issue.id,
    73	            reason: error instanceof Error ? error.message : String(error),
    74	          });
    75	        }
    76	      }
    77	    }
    78	  });
    79	}
--- registry
     1	/**
     2	 * Wires every subscriber at process start. Called once from `src/instrumentation.ts`; the only module that knows the full listener set.
     3	 *
     4	 * Must call (do not reimplement): subscribe, registerActivityListeners, registerSearchListeners, registerUsageListeners, registerWebhookListeners
     5	 */
     6	import { subscribe } from "@/lib/event-bus";
     7	import { createLogger } from "@/lib/logger";
     8	import { enqueue } from "@/server/jobs/queue";
     9	import { toIsoTimestamp } from "@/types/common";
    10	import { registerActivityListeners } from "./activity-service";
    11	import { registerSearchListeners } from "./search-service";
    12	import { registerUsageListeners } from "./usage-service";
    13	import { registerWebhookListeners } from "./webhook-service";
    14	import type { Unsubscribe } from "@/types/event";
    15	
    16	/**
    17	 * Importing this module also loads `notification-service` transitively, which
    18	 * attaches the notification fan-out on first import — that hub has no
    19	 * `register*` entry point of its own.
    20	 */
    21	import "./notification-service";
    22	
    23	const logger = createLogger("event-registry");
    24	
    25	/** Non-null between `registerEventHandlers()` and `unregisterEventHandlers()`. */
    26	let detach: Unsubscribe | null = null;
    27	
    28	/**
    29	 * Attaches every subscriber exactly once. Idempotent: `instrumentation.ts`
    30	 * runs per server process, but a hot reload in dev can call it again and must
    31	 * not double-deliver every event.
    32	 */
    33	export function registerEventHandlers(): void {
    34	  if (detach !== null) return;
    35	
    36	  const offs: Unsubscribe[] = [
    37	    registerActivityListeners(),
    38	    registerSearchListeners(),
    39	    registerUsageListeners(),
    40	    registerWebhookListeners(),
    41	    registerDigestBridge(),
    42	  ];
    43	
    44	  detach = () => {
    45	    for (const off of offs) off();
    46	  };
    47	
    48	  logger.info("event handlers registered", { groups: offs.length });
    49	}
    50	
    51	export function unregisterEventHandlers(): void {
    52	  detach?.();
    53	  detach = null;
    54	}
    55	
    56	/**
    57	 * The one piece of wiring that belongs to no single service: turning a
    58	 * `digest.due` event into a queued job. Keeping it here rather than inside
    59	 * `DigestService` stops the service layer from depending on the job layer.
    60	 */
    61	function registerDigestBridge(): Unsubscribe {
    62	  return subscribe("digest.due", (payload) => {
    63	    enqueue({
    64	      id: `digest:${payload.orgId}:${payload.recipientId}`,
    65	      kind: "digest-email",
    66	      runAt: toIsoTimestamp(new Date()),
    67	      attempts: 0,
    68	      payload: {
    69	        orgId: payload.orgId,
    70	        recipientId: payload.recipientId,
    71	        windowStart: payload.windowStart,
    72	      },
    73	    });
    74	  });
    75	}

