     1	import type {
     2	  EventHandler,
     3	  TaskflowEventMap,
     4	  TaskflowEventPayload,
     5	  TaskflowEventType,
     6	  Unsubscribe,
     7	} from "@/types/event";
     8	
     9	/**
    10	 * In-process, typed publish/subscribe bus.
    11	 *
    12	 * Taskflow keeps `IssueService`, `NotificationService`, `ActivityService`, the
    13	 * search indexer and the webhook dispatcher decoupled: writers `emit()`, and
    14	 * every reactive concern `subscribe()`s at module init (see
    15	 * `src/server/services/event-registry.ts`). Handlers are isolated — one
    16	 * throwing handler never fails the emit or the sibling handlers.
    17	 */
    18	
    19	type HandlerSet = Set<EventHandler<TaskflowEventType>>;
    20	
    21	const handlers = new Map<TaskflowEventType, HandlerSet>();
    22	
    23	const errorSinks = new Set<(type: TaskflowEventType, error: unknown) => void>();
    24	
    25	/** Registers a handler for one event type. Call the return value to detach. */
    26	export function subscribe<K extends TaskflowEventType>(
    27	  type: K,
    28	  handler: EventHandler<K>,
    29	): Unsubscribe {
    30	  const set = handlers.get(type) ?? new Set();
    31	  set.add(handler as EventHandler<TaskflowEventType>);
    32	  handlers.set(type, set);
    33	  return () => {
    34	    set.delete(handler as EventHandler<TaskflowEventType>);
    35	  };
    36	}
    37	
    38	/** Registers a handler that detaches itself after the first delivery. */
    39	export function subscribeOnce<K extends TaskflowEventType>(
    40	  type: K,
    41	  handler: EventHandler<K>,
    42	): Unsubscribe {
    43	  const off = subscribe(type, (payload) => {
    44	    off();
    45	    return handler(payload);
    46	  });
    47	  return off;
    48	}
    49	
    50	/**
    51	 * Publishes an event to every subscriber. Resolves once all handlers settle;
    52	 * rejected handlers are reported to the error sinks, never rethrown.
    53	 */
    54	export async function emit<K extends TaskflowEventType>(
    55	  type: K,
    56	  payload: TaskflowEventPayload<K>,
    57	): Promise<void> {
    58	  const set = handlers.get(type);
    59	  if (!set || set.size === 0) return;
    60	
    61	  const results = await Promise.allSettled(
    62	    [...set].map(async (handler) => {
    63	      await (handler as EventHandler<K>)(payload);
    64	    }),
    65	  );
    66	
    67	  for (const result of results) {
    68	    if (result.status === "rejected") {
    69	      reportHandlerError(type, result.reason);
    70	    }
    71	  }
    72	}
    73	
    74	/** Fire-and-forget variant for call sites that must not await delivery. */
    75	export function emitAndForget<K extends TaskflowEventType>(
    76	  type: K,
    77	  payload: TaskflowEventPayload<K>,
    78	): void {
    79	  void emit(type, payload).catch((error: unknown) => {
    80	    reportHandlerError(type, error);
    81	  });
    82	}
    83	
    84	export function onHandlerError(
    85	  sink: (type: TaskflowEventType, error: unknown) => void,
    86	): Unsubscribe {
    87	  errorSinks.add(sink);
    88	  return () => {
    89	    errorSinks.delete(sink);
    90	  };
    91	}
    92	
    93	function reportHandlerError(type: TaskflowEventType, error: unknown): void {
    94	  for (const sink of errorSinks) {
    95	    try {
    96	      sink(type, error);
    97	    } catch {
    98	      // A failing error sink must never escalate.
    99	    }
   100	  }
   101	}
   102	
   103	/** Number of live subscribers for an event; used by tests and diagnostics. */
   104	export function subscriberCount(type: TaskflowEventType): number {
   105	  return handlers.get(type)?.size ?? 0;
   106	}
   107	
   108	/** Detaches every handler. Test-only — never call from application code. */
   109	export function resetEventBus(): void {
   110	  handlers.clear();
   111	  errorSinks.clear();
   112	}
   113	
   114	export type { TaskflowEventMap, TaskflowEventType, Unsubscribe };
--- event types
     1	import type {
     2	  CommentId,
     3	  IssueId,
     4	  MemberId,
     5	  OrgId,
     6	  ProjectId,
     7	  UserId,
     8	  IsoTimestamp,
     9	} from "./common";
    10	import type { IssueStatus, IssuePriority } from "./issue";
    11	import type { Role } from "./member";
    12	import type { PlanId, LimitedResource } from "./billing";
    13	import type { FeatureFlagKey } from "./feature-flag";
    14	
    15	/** Fields present on every event payload; the bus stamps them on `emit`. */
    16	export interface EventEnvelope {
    17	  readonly orgId: OrgId;
    18	  readonly actorId: UserId | null;
    19	  readonly occurredAt: IsoTimestamp;
    20	}
    21	
    22	/**
    23	 * The complete catalogue of domain events. `emit()` and `subscribe()` in
    24	 * `src/lib/event-bus.ts` are keyed on this map, so adding an event here is the
    25	 * only way to introduce one — services, jobs and the webhook dispatcher all
    26	 * derive their handler signatures from it.
    27	 */
    28	export interface TaskflowEventMap {
    29	  "project.created": EventEnvelope & {
    30	    projectId: ProjectId;
    31	    name: string;
    32	    slug: string;
    33	  };
    34	  "project.archived": EventEnvelope & {
    35	    projectId: ProjectId;
    36	    issuesArchived: number;
    37	  };
    38	  "project.restored": EventEnvelope & { projectId: ProjectId };
    39	  "issue.created": EventEnvelope & {
    40	    issueId: IssueId;
    41	    projectId: ProjectId;
    42	    title: string;
    43	    assigneeId: UserId | null;
    44	    priority: IssuePriority;
    45	  };
    46	  "issue.updated": EventEnvelope & {
    47	    issueId: IssueId;
    48	    projectId: ProjectId;
    49	    changedFields: readonly string[];
    50	  };
    51	  "issue.status_changed": EventEnvelope & {
    52	    issueId: IssueId;
    53	    projectId: ProjectId;
    54	    from: IssueStatus;
    55	    to: IssueStatus;
    56	  };
    57	  "issue.assigned": EventEnvelope & {
    58	    issueId: IssueId;
    59	    projectId: ProjectId;
    60	    previousAssigneeId: UserId | null;
    61	    assigneeId: UserId;
    62	  };
    63	  "issue.archived": EventEnvelope & { issueId: IssueId; projectId: ProjectId };
    64	  "issue.overdue": EventEnvelope & {
    65	    issueId: IssueId;
    66	    projectId: ProjectId;
    67	    dueAt: IsoTimestamp;
    68	    assigneeId: UserId | null;
    69	  };
    70	  "comment.created": EventEnvelope & {
    71	    commentId: CommentId;
    72	    issueId: IssueId;
    73	    mentionedUserIds: readonly UserId[];
    74	  };
    75	  "comment.deleted": EventEnvelope & { commentId: CommentId; issueId: IssueId };
    76	  "member.invited": EventEnvelope & { email: string; role: Role };
    77	  "member.joined": EventEnvelope & { memberId: MemberId; userId: UserId; role: Role };
    78	  "member.role_changed": EventEnvelope & {
    79	    memberId: MemberId;
    80	    from: Role;
    81	    to: Role;
    82	  };
    83	  "member.removed": EventEnvelope & { memberId: MemberId; userId: UserId };
    84	  "billing.plan_changed": EventEnvelope & { from: PlanId; to: PlanId };
    85	  "billing.limit_exceeded": EventEnvelope & {
    86	    resource: LimitedResource;
    87	    limit: number;
    88	    used: number;
    89	  };
    90	  "flag.toggled": EventEnvelope & { flag: FeatureFlagKey; enabled: boolean };
    91	  "digest.due": EventEnvelope & { recipientId: UserId; windowStart: IsoTimestamp };
    92	  "search.reindex_requested": EventEnvelope & {
    93	    subjectKind: "issue" | "comment" | "project";
    94	    subjectId: string;
    95	  };
    96	  "webhook.delivery_requested": EventEnvelope & {
    97	    eventType: string;
    98	    payload: Readonly<Record<string, unknown>>;
    99	  };
   100	}
   101	
   102	export type TaskflowEventType = keyof TaskflowEventMap;
   103	
   104	export type TaskflowEventPayload<K extends TaskflowEventType> =
   105	  TaskflowEventMap[K];
   106	
   107	/** A handler registered with `subscribe()`. May be async; errors are isolated. */
   108	export type EventHandler<K extends TaskflowEventType> = (
   109	  payload: TaskflowEventPayload<K>,
   110	) => void | Promise<void>;
   111	
   112	/** Returned by `subscribe()`; calling it removes the handler. */
   113	export type Unsubscribe = () => void;

