   161	    const northIssue = await insertIssue(north, { title: "North late", dueAt: PAST });
   162	    const acmeIssue = await insertIssue(acme, { title: "Acme late", dueAt: PAST });
   163	
   164	    const seen: Array<{ orgId: string; issueId: string }> = [];
   165	    detachers.push(
   166	      subscribe("issue.overdue", (payload) => {
   167	        seen.push({ orgId: payload.orgId, issueId: payload.issueId });
   168	      }),
   169	    );
   170	
   171	    await runOverdueIssueJob(NOW);
   172	
   173	    expect(seen).toContainEqual({ orgId: north.org.id, issueId: northIssue.id });
