/**
 * Member absences: who may set them, how they redirect assignments and alerts
 * while in effect, and what member removal does to them.
 *
 * Each case builds its own tenant so notification counts never leak between cases.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import * as memberAbsenceRepo from "@/server/repositories/member-absence-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as memberService from "@/server/services/member-service";
import { listNotifications } from "@/server/services/notification-service";
import { NotFoundError } from "@/server/services/_support";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";
import type { NotificationKind } from "@/types/notification";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

/** A window that covers both the real clock and the sweep instant used below. */
const OPEN = {
  startsAt: toIsoTimestamp("2000-01-01T00:00:00.000Z"),
  endsAt: toIsoTimestamp("2999-01-01T00:00:00.000Z"),
};
const NOT_YET = {
  startsAt: toIsoTimestamp("2999-01-01T00:00:00.000Z"),
  endsAt: toIsoTimestamp("2999-06-01T00:00:00.000Z"),
};
const ENDED = {
  startsAt: toIsoTimestamp("2019-01-01T00:00:00.000Z"),
  endsAt: toIsoTimestamp("2020-01-01T00:00:00.000Z"),
};

const SWEEP_AT = new Date("2026-06-01T07:00:00.000Z");
const PAST_DUE = "2026-01-01T00:00:00.000Z";

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  cleanup();
});

/** Collects every payload delivered for one event type during a test. */
function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

let counter = 0;
async function freshTenant(): Promise<Tenant> {
  counter += 1;
  const tenant = await createTenant(`absence-${counter}`, "growth");
  await usageRepo.recomputeUsage(tenant.org.id);
  return tenant;
}

function setAbsence(
  tenant: Tenant,
  userId: UserId,
  delegateUserId: UserId | null,
  window: { startsAt: IsoTimestamp; endsAt: IsoTimestamp } = OPEN,
) {
  return memberService.setAbsence(tenant.actors.owner, {
    orgId: tenant.org.id,
    userId,
    delegateUserId,
    note: null,
    ...window,
  });
}

async function alertsFor(tenant: Tenant, recipientId: UserId, kind: NotificationKind) {
  const page = await listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id,
    recipientId,
    unreadOnly: false,
    kind: [kind],
    limit: 25,
    cursor: null,
  });
  return page.items;
}

async function createAssigned(tenant: Tenant, assigneeId: UserId | null, dueAt: string | null = null) {
  return issueService.createIssue(
    tenant.actors.owner,
    issueInput(tenant.org.id, tenant.project.id, { title: "Assigned work", assigneeId, dueAt }),
  );
}

describe("setting and reading an absence", () => {
  it("stores the window, delegate and note, and returns exactly what was stored", async () => {
    const tenant = await freshTenant();

    const set = await memberService.setAbsence(tenant.actors.member, {
      orgId: tenant.org.id,
      userId: tenant.userIds.member,
      delegateUserId: tenant.userIds.admin,
      startsAt: OPEN.startsAt,
      endsAt: OPEN.endsAt,
      note: "Conference",
    });

    expect(set).toEqual({
      orgId: tenant.org.id,
      userId: tenant.userIds.member,
      delegateUserId: tenant.userIds.admin,
      startsAt: OPEN.startsAt,
      endsAt: OPEN.endsAt,
      note: "Conference",
    });
    await expect(
      memberService.getAbsence(tenant.actors.viewer, tenant.org.id, tenant.userIds.member),
    ).resolves.toEqual(set);
  });

  it("replaces an earlier absence rather than adding a second one", async () => {
    const tenant = await freshTenant();
    await setAbsence(tenant, tenant.userIds.member, tenant.userIds.admin);

    const replacement = await memberService.setAbsence(tenant.actors.owner, {
      orgId: tenant.org.id,
      userId: tenant.userIds.member,
      delegateUserId: null,
      startsAt: NOT_YET.startsAt,
      endsAt: NOT_YET.endsAt,
      note: null,
    });

    expect(replacement.delegateUserId).toBeNull();
    await expect(
      memberService.getAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.member),
    ).resolves.toEqual(replacement);
  });

  it("returns a scheduled absence that has not started yet", async () => {
    const tenant = await freshTenant();
    const set = await setAbsence(tenant, tenant.userIds.member, null, NOT_YET);

    await expect(
      memberService.getAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.member),
    ).resolves.toEqual(set);
  });

  it("returns null once the absence has ended, and after it is cleared", async () => {
    const tenant = await freshTenant();
    await setAbsence(tenant, tenant.userIds.member, null, ENDED);

    await expect(
      memberService.getAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.member),
    ).resolves.toBeNull();

    await memberService.clearAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.member);
    await memberService.clearAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.member);

    await expect(
      memberService.getAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.member),
    ).resolves.toBeNull();
  });
});

describe("validation", () => {
  it("rejects an end that is not after the start", async () => {
    const tenant = await freshTenant();

    await expect(
      setAbsence(tenant, tenant.userIds.member, null, {
        startsAt: OPEN.endsAt,
        endsAt: OPEN.startsAt,
      }),
    ).rejects.toThrow(/endsAt/);
    await expect(
      setAbsence(tenant, tenant.userIds.member, null, {
        startsAt: OPEN.startsAt,
        endsAt: OPEN.startsAt,
      }),
    ).rejects.toThrow(/endsAt/);
  });

  it("rejects naming oneself as the delegate", async () => {
    const tenant = await freshTenant();

    await expect(
      setAbsence(tenant, tenant.userIds.member, tenant.userIds.member),
    ).rejects.toThrow(/own delegate/);
  });

  it("refuses a delegate who is not an active member of the workspace", async () => {
    const tenant = await freshTenant();
    const outsider = await freshTenant();

    await expect(
      setAbsence(tenant, tenant.userIds.member, outsider.userIds.member),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("refuses a member who is not in the workspace", async () => {
    const tenant = await freshTenant();
    const outsider = await freshTenant();

    await expect(
      setAbsence(tenant, outsider.userIds.member, null),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      memberService.getAbsence(tenant.actors.owner, tenant.org.id, outsider.userIds.member),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("refuses a removed member", async () => {
    const tenant = await freshTenant();
    const removed = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!removed) throw new Error("fixture member missing");
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: removed.id,
    });

    await expect(
      setAbsence(tenant, tenant.userIds.viewer, null),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("refuses an organization outside the actor's workspace on every operation", async () => {
    const tenant = await freshTenant();
    const other = await freshTenant();
    const foreignOrg: OrgId = other.org.id;

    await expect(
      memberService.setAbsence(tenant.actors.owner, {
