    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: target.id,
    });

    expect(await memberAbsenceRepo.findAbsence(tenant.org.id, tenant.userIds.member)).toBeNull();
  });

  it("leaves an absence without a delegate when the delegate is removed", async () => {
    const tenant = await freshTenant();
    const set = await setAbsence(tenant, tenant.userIds.member, tenant.userIds.admin);
    const delegate = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    if (!delegate) throw new Error("fixture delegate missing");

    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: delegate.id,
    });

    const remaining = await memberAbsenceRepo.findAbsence(tenant.org.id, tenant.userIds.member);
    expect(remaining).toEqual({ ...set, delegateUserId: null });

    const issue = await createAssigned(tenant, tenant.userIds.member);
    expect(issue.assigneeId).toBe(tenant.userIds.member);
  });
});

describe("workspaces are independent", () => {
  it("does not redirect work in another workspace the same user belongs to", async () => {
    const home = await freshTenant();
    const elsewhere = await freshTenant();
    await memberRepo.insertMember(elsewhere.org.id, home.userIds.member, "member", null);
    await setAbsence(home, home.userIds.member, home.userIds.admin);

    const issue = await createAssigned(elsewhere, home.userIds.member);

    expect(issue.assigneeId).toBe(home.userIds.member);
    await expect(
      memberService.getAbsence(elsewhere.actors.owner, elsewhere.org.id, home.userIds.member),
    ).resolves.toBeNull();
  });
});

